INSERT INTO `ITAItem` VALUES (1,'ตัวชี้วัดที่ 1 การเปิดเผยข้อมูล',NULL,NULL,0,NULL,0,'2026-09-02 04:43:02.973','2026-09-02 07:05:58.021',0),(2,'MOIT1 หน่วยงานมีการวางระบบโดยการกำหนดมาตรการการเผยแพร่ข้อมูลต่อสาธารณะ ผ่านเว็บไซต์ของหน่วยงาน',NULL,NULL,1,1,0,'2026-09-02 04:43:55.826','2026-09-02 07:08:59.422',0),(3,'1. คำสั่ง / ประกาศ ที่ระบุกรอบแนวทาง',NULL,'/uploads/ita/1788324319809-866201363-MOIT1.1คำสั่ง.pdf',2,2,0,'2026-09-02 04:45:19.820','2026-09-02 07:09:27.839',0),(4,'2. รายงานผลการกำกับติดตามการเผยแพร่ข้อมูลต่อสาธารณะผ่านเว็บไซต์ของหน่วยงานในปีที่ผ่านมา (ของปีงบประมาณ พ.ศ. 2568)',NULL,NULL,2,2,1,'2026-09-02 04:46:25.093','2026-09-02 04:46:25.093',0),(5,'1.1 มีบันทึกข้อความ ที่ผู้บริหารลงนามในคำสั่ง / ประกาศ และมีการขออนุญาต นำไปเผยแพร่บนเว็บไซต์ของหน่วยงาน',NULL,'/uploads/ita/1788332264298-671901238-MOIT1.1คำสั่ง.pdf',3,3,0,'2026-09-02 06:57:44.358','2026-09-02 06:57:44.358',0),(6,'ตัวชี้วัดที่ 2 การจัดซื้อจัดจ้างและการจัดหาพัสดุ',NULL,NULL,0,NULL,1,'2026-09-02 06:58:34.390','2026-09-02 06:58:34.390',0),(7,'1.2 มีคำสั่ง / ประกาศ โดยผู้บริหารสูงสุดของหน่วยงาน เป็นไปตามข้อ 1. (รายละเอียดข้อมูลประกอบข้อคำถาม).',NULL,NULL,3,3,1,'2026-09-02 07:09:47.650','2026-09-02 07:09:47.650',0),(8,'1.3 มีกรอบแนวทางการเผยแพร่ข้อมูลต่อสาธารณะผ่านเว็บไซต์ของหน่วยงาน รายละเอียดเนื้อหาในข้อมูลประกอบข้อคำถามข้อ 2. (ข้อ 2.1 มีลักษณะ / ประเภทข้อมูลที่หน่วยงานต้องเผยแพร่ต่อสาธารณะ และข้อ 2.2 มีก',NULL,NULL,3,3,2,'2026-09-02 07:09:58.402','2026-09-02 07:09:58.402',0),(9,'1.4 มีแบบฟอร์มการเผยแพร่ข้อมูลต่อสาธารณะผ่านเว็บไซต์ของหน่วยงาน',NULL,NULL,3,3,3,'2026-09-02 07:10:07.421','2026-09-02 07:10:07.421',0),(10,'2.1 มีบันทึกข้อความ ที่ผู้บริหารลงนามรับทราบรายงานฯ และมีการขออนุญาตนำไปเผยแพร่บนเว็บไซต์ของหน่วยงาน',NULL,NULL,3,4,0,'2026-09-02 07:10:46.396','2026-09-02 07:10:46.396',0),(11,'2.2 มีรายงานผลการกำกับติดตามการเผยแพร่ข้อมูลต่อสาธารณะผ่านเว็บไซต์ของหน่วยงานในปีที่ผ่านมา (ของปีงบประมาณ พ.ศ. 2568)',NULL,NULL,3,4,1,'2026-09-02 07:10:59.810','2026-09-02 07:10:59.810',0),(12,'MOIT 3 หน่วยงานมีรายงานการวิเคราะห์ผลการจัดซื้อจัดจ้างและการจัดหาพัสดุ ของปีงบประมาณ พ.ศ. 2568',NULL,NULL,1,6,0,'2026-09-02 07:11:50.605','2026-09-02 07:11:50.605',0),(13,'MOIT4หน่วยงานมีการวางระบบการจัดซื้อจัดจ้างหรือการจัดหาพัสดุ ประจำปีงบประมาณ พ.ศ. 2569',NULL,NULL,1,6,1,'2026-09-02 07:11:59.831','2026-09-02 07:11:59.831',0),(14,'1. มีบันทึกข้อความ ที่ผู้บริหารลงนามรับทราบรายงานการวิเคราะห์ผลการจัดซื้อจัดจ้างและการจัดหาพัสดุ ประจำปีงบประมาณ พ.ศ. 2568 และมีการขออนุญาตนำไปเผยแพร่บนเว็บไซต์ของหน่วยงาน',NULL,NULL,2,12,0,'2026-09-02 07:12:14.096','2026-09-02 07:12:14.096',0),(15,'ข้อ 1. ประกาศเผยแพร่แผนการจัดซื้อจัดจ้างและการจัดหาพัสดุ ประจำปีของหน่วยงาน ภายใน 30 วันทำการ ระบุวันที่ที่ได้รับการจัดสรรงบประมาณในช่องคำอธิบายชี้แจงประกอบหลักฐาน วันที่ที่ได้ ทำการประกาศเผย',NULL,NULL,2,13,0,'2026-09-02 07:12:28.015','2026-09-02 07:12:28.015',0),(16,'1.1. มีบันทึกข้อความ ที่ผู้บริหารลงนามรับทราบแผนการจัดซื้อจัดจ้างประจำปีของหน่วยงานและมีการขออนุญาตนำไปเผยแพร่บนเว็บไซต์ของหน่วยงาน',NULL,NULL,3,15,0,'2026-09-02 07:12:39.953','2026-09-02 07:12:39.953',0),(17,'1.2. มีหนังสือจัดสรรงบประมาณของหน่วยงาน ประจำปีงบประมาณ พ.ศ. 2569',NULL,NULL,3,15,1,'2026-09-02 07:12:49.285','2026-09-02 07:12:49.285',0),(18,'ตัวชี้วัดที่ 3 การบริหารและพัฒนาทรัพยากรบุคคล',NULL,NULL,0,NULL,2,'2025-09-02 09:01:30.289','2025-09-02 09:02:07.938',0),(20,'ตัวชี้วัดที่ 1 การเปิดเผยข้อมูล',NULL,NULL,0,NULL,3,'2026-09-02 09:12:51.735','2026-09-02 09:12:51.735',2025);
